    'translate': { tier: 5, note: 'Exclude. translate/main.js:1-40 is a crowd-translation editor: language picker, text rows, localStorage edits (sn_tr_v5), TOML export and a formsubmit.co POST (' },
    'solar': { tier: 5, note: 'Exclude by default. It is a light-theme three-column analysis dashboard for one stadium site;' },
