    'forge': { tier: 3, default: true, hook: true, note: 'WebGPU planet generator (pages/forge/saver.js): a seeded tour that alternates rocky worlds and gas giants (a new member of each preset family per seed), each generated in workers while the last plays; clock at 20 min/s so the cloud decks evolve; orbits, sunrise over the limb through the scattering atmosphere, push-ins on the great spot or the highest point, ring passes, 6 h/s time-lapses under the starfield with the granulated sun in frame; cuts every 5-12 s; plate with the family, the rate, the noise parameters and the scattering, star-count and limb-darkening TeX, no code.' },
    'galaxy': { tier: 1, hook: true, default: true, note: 'saver.js: seeded shuffle of 7 presets and random galaxies of 7 types; orbit, face-on, dive into the disk, bulge fly-by, edge-on and tidal-pair shots, 5-12 s, framed in plateBand; plate has type, parameters and TeX, no code' },
    'blackhole': { tier: 1, default: true, hook: true, note: 'Generic fallback is enough: frame() starts unconditionally (main.js:282) even before the GPU warning is dismissed (warnDismissed only gates the UI reveal, main.' },
