    'qave': { tier: 2, default: true, hook: true, note: 'Already plays and orbits idle: VS.playing=true, speed 2, autoRotate true speed 0.55 (core.js:29-31,50).' },
    'qft-flow': { tier: 'excluded', note: 'Pulled from the screensaver by the user (2026-10-02). Its hook stays in the page.' },
    'qft-store': { tier: 5, note: 'Exclude. Page is a form: payload textarea #payload, register steppers, SVG dials built in buildDials (main.js:123), decoded text and badge.' },
    'frqi': { tier: 3, default: true, hook: true, note: 'Stack autorotates idle (initGL, autoRotateSpeed 0.5) but layers do not advance.' },
    'protein-viewer': { tier: 3, default: true, hook: true, note: 'Draws only when S.dirty (app/loop.js);' },
    'protein-folding': { tier: 2, default: true, hook: true, note: 'Sim workers run idle (S.running=true) and camera orbits after 2 s idle (S.orbit=!REDUCED, main.js:541).' },
    'alphafold': { tier: 3, default: true, hook: true, note: 'Long scrolling explainer;' },
    'virus-atlas': { tier: 4, default: true, hook: true, note: 'Virus Atlas (PDB structures, CC0): own saver tour (saver.js, shots.js, regions.js) where every shot draws from seeded weighted bags with no back-to-back repeats; led by exploded views (parts leave one group at a time along 5-, 3-, 2-fold or radial lines or capsomer by capsomer, hold apart while the camera flies between two parts, then close) and inspections (a pentamer, hexamer, hexon trimer, asymmetric unit, icosahedron face, TMV rod section, fibril layers or protofilament, virion spike, protomer or the RBD lifts out while the rest turns to a ghost or moves away; push-in and turn, morph to tube or space-filling, colour by chain or secondary structure, plate names chains, size in nm and symmetry), and 3-shot chapters on one capsid with no cut (explode -> inspect from the open shell -> peel); plus 12 effects (assemble, peel in six orders: camera side, latitude, copy by copy, outer shell, spiral, random tiles, some re-closing; inside: peel then the camera goes in to the inner surface or inner shell; explode along 5-, 3-, 2-fold or radial axes; implode; slice or a sweeping slab; axes; spike push-in; fibril growth; view morph; protein; scale ladder), 7 views (beads, space-filling, backbone tube, subunit blobs, lattice cage, glow, toon) with mid-shot morphs labelled as drawing changes, 9 colour schemes, 5 palettes, 6 light rigs and 7 camera moves (orbit, push-in, pull-out, crane, arc, dutch roll, fly-by); 5-12 s cuts framed in plateBand; plate shows name, PDB ID, disease, view, colour scheme and TeX (T number, helical screw), no code; restores the entry, view and colours on exit.' },
    'mrna-vaccine': { tier: 3, default: true, hook: true, note: 'Long scrolling explainer; saver.js plays a seeded shuffle of four 2D scenes (LNP journey, translation, 2P spike, strand), 5-12 s cuts, TeX plates.' },
    'circular-rydberg': { tier: 3, default: true, hook: true, note: 'Research explainer; saver.js plays a seeded shuffle of seven shots (ring growing with n, cloud to ring, wave packet, l = 0 vs circular, preparation ladder, cascade, lifetime data), 6-12 s cuts, TeX plates, no code.' },
    'ct-explained': { tier: 3, default: true, hook: true, note: 'Long scrolling explainer; saver.js replays the hero scan full screen: a fan-beam gantry turns once around a seeded phantom (head, chest, Shepp-Logan, walnut, suitcase, hip implant) while the sinogram fills and FBP builds view by view, seeded colour maps, Radon and FBP TeX on the plate, ASTRA Toolbox credit line, no code. The CT lab has the larger reel.' },
    'sstv': { tier: 3, default: true, hook: true, note: 'Long scrolling explainer; saver.js plays a seeded plan of 6-12 s shots, no kind twice in a row: the CRT receiving pictures in different modes and phosphors with a waterfall beside it, a beam close-up near real time, the VIS header decoded bit by bit, a noisy slanted picture repainted by the sync fit, an ISS-style event card in a PD mode. Real encode/decode round trip, no sound, mode, line time and the f-to-Y TeX on the plate, no code.' },
    'human-skull': { tier: 3, default: true, hook: true, note: 'Intro flies parts in and opens Anatomy layout;' },
    'outbreak': { tier: 3, default: true, hook: true, note: 'Outbreak (public-health epidemiology of natural diseases): director.js and saver.js run a seeded tour that picks a disease and policy plan, seeds an outbreak, follows flight arcs across the globe, cycles the globe styles and shows the compartment model TeX on the plate, no code.' },
    'neuron-lab': { tier: 3, default: true, hook: true, note: 'Neuron Lab (own engine after NEURON, BSD-3-Clause): saver.js plays a seeded shuffle of ten shots: six on one procedural cell (spikes running back into a dendrite close-up, a slow orbit with distal synapses, a distal Exp2Syn pull-back, the V-n phase plane and the m h n gates on a board beside a tonic cell, a ride down the axon) and four on networks of full cells (a spike handed down a chain with the camera following it, a self-sustaining ring, inhibition silencing a ring, a random circuit with its raster on a board); 6-12 s cuts, spring camera in the plate band, cable, HH and delay TeX on the plate, no code.' },
    'neuron-network': { tier: 3, default: true, hook: true, note: 'Neural Network (own NetCon engine after NEURON): saver.js shuffles five shots (an avalanche from random pulses in a quiet column, a raster that writes itself across a board like a score, the PING gamma column orbit, a push-in among cells, a wave running round the ring with the camera on the front), 6-12 s cuts, plate with model, cell and NetCon counts and TeX, no code.' },
    'human-skeleton': { tier: 3, default: true, hook: true, note: 'Loads eight groups with dissolve-in, then static: S.show.spin=false (app/state.js:24), loop draws only when dirty.' },
