    'universal-joints': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: a single Cardan joint, double Cardan Z and W and a Rzeppa CV joint, with the shaft angle swinging about a seeded 15-35 deg.' },
    'ball-screw': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: an ACME lead screw that self-locks, a four-start lead screw and a ball screw with recirculating balls; whole stage, the nut cut open, exploded, part close-ups.' },
    'ratchets': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: a ratchet and pawl, a 14-sprag clutch and a 3-pawl bicycle freehub, each driving one way and slipping the other.' },
    'sewing-machine': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: a cutaway lockstitch machine runs its stitch cycle (needle, take-up lever, rotary hook, feed dog) while the camera tours the head and the hook.' },
    'swashplate-pump': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: 7-, 8- and 9-piston swashplate pumps with the swash angle sweeping, whole pump, pistons close in, side view of the tilt, valve plate kidneys, exploded, part close-ups.' },
    'calculators': { tier: 3, default: true, hook: true, note: 'Mechanism page with its own saver tour: the Pascaline sautoir carry and the Curta stepped drum, with each carry rippling through the digit wheels.' },
